import json
from pathlib import Path

p = Path(__file__).parent / 'CLAIMS.jsonl'
rows = [
    {'id':'w496-C0120-002','kind':'source-scope correction','statement':'The cited Chatterjee 2008 Section 8 theorem bounds the variance of a free-endpoint Gaussian up-right path maximum in Z^2, not an arbitrary-dimensional positive-temperature log partition function.','assumptions':'arXiv:0810.4221v2, Section 8 and Section 12(3).','source':'https://arxiv.org/pdf/0810.4221; local problems.jsonl line 120 and sources.jsonl line 29.','source_quote':'Improve the fluctuation exponent in directed polymers.','proof':'Source model and Theorem 8.1 read directly; Section 12(2) separately lists dimension >=3 chaos as open. See SOURCE_STATUS.json.','independent_reviewer':'w497, pending','remaining_gap':'Current openness and possible later extensions not certified.','status':'sketch'},
    {'id':'w496-C0120-003','kind':'conditional reduction','statement':'For the source-model maximum M_n with degree-k Gaussian chaos masses v_nk, Var(M_n)<=sum_{k<=K}v_nk+n/(K+1). A bound on the sum through K=ceil(n^delta) of order n^(1-delta) implies the same power variance bound.','assumptions':'iid standard Gaussian weights, n vertices per path, finite free-endpoint up-right paths, 0<delta<1.','source':'Independent derivation, INDEPENDENT_DERIVATION.md section 1.','proof':'Hermite Dirichlet form sum k v_nk=n, then bound the tail by n/(K+1).','independent_reviewer':'w497, pending','remaining_gap':'No bound on polynomial-degree low-chaos mass has been proved.','status':'sketch'},
    {'id':'w496-C0120-004','kind':'exact decomposition','statement':'For the source model, M_n=sum_t A_t+M_n(R), with A_t the Gaussian average of the t+1 vertices in layer t and R the within-layer centered environment; Var(M_n)=H_n+Var(M_n(R)).','assumptions':'iid N(0,1), n vertices from the origin moving up/right, free endpoint.','source':'Independent derivation, INDEPENDENT_DERIVATION.md section 2.','proof':'Every path visits one vertex per layer; zero cross covariance and joint Gaussianity make all layer averages jointly independent of all residuals.','independent_reviewer':'w497, pending','remaining_gap':'Residual variance is unbounded by this argument; residual coordinates are correlated.','status':'sketch'},
    {'id':'w496-C0120-005','kind':'abstract spectral counterexample','statement':'Fixed-degree chaos suppression and fixed-positive-noise gradient decorrelation, even with Gaussian Dirichlet energy n, do not imply a power variance bound.','assumptions':'General Gaussian Sobolev functions; the functions in this counterexample are not convex or globally Lipschitz.','source':'Independent derivation, INDEPENDENT_DERIVATION.md section 3.','proof':'F_n=sqrt(n/ceil(log n)) H_{ceil(log n)}(G), normalized Hermite polynomials; variance n/ceil(log n), Dirichlet energy n, gradient covariance ratio exp(-(ceil(log n)-1)u).','independent_reviewer':'w497, pending','remaining_gap':'Scope excludes actual polymer maxima; stronger geometric control is supplied separately by the fan example.','status':'sketch'},
    {'id':'w496-C0120-006','kind':'geometric counterexample','statement':'A sequence of iid-Gaussian n-vertex layered path maxima can be convex, sqrt(n)-Lipschitz, have path-indicator gradients of squared norm n, and exhibit chaos at noise u_n=16 log log n/log n, while Var(M_n)>=c n/log n and therefore has no fixed power improvement.','assumptions':'Fan graph with n disjoint branches of n-1 vertices and a common root; graph degree grows with n. This is not the fixed Z^2 lattice.','source':'Independent derivation, GAUSSIAN_FAN_OBSTRUCTION.md.','proof':'Exact reduction to 1+sqrt(n-1) times a maximum of n Gaussians; separated quantile events and Mills bounds give a c/log n variance lower bound; a bivariate Gaussian tail union bound gives the vanishing-noise overlap estimate.','independent_reviewer':'w497, pending','remaining_gap':'Independent proof audit pending. No impossibility for the source lattice is asserted.','status':'sketch'}
]
existing = {json.loads(s)['id'] for s in p.read_text(encoding='utf-8').splitlines() if s.strip()}
with p.open('a', encoding='utf-8') as f:
    for row in rows:
        if row['id'] not in existing:
            f.write(json.dumps(row, ensure_ascii=False) + '\n')
print('saved_claim_rows', len(existing | {r['id'] for r in rows}))
